#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using HabitatShift.Core;using UnityEditor;using UnityEngine;
namespace HabitatShift.LevelLabR10 {
public sealed class R10Window:EditorWindow {
 R10EditorState state;readonly R10Selection selected=new R10Selection();R10Tool tool;R10Playtest play;R10View view=R10View.AUTHORING;string dragId,dragKind,path;bool grid=true,targets=true,choke=true,reachability,dependency,solution,showGenerator;R10GeneratorProfile generatorProfile=new R10GeneratorProfile();R10RuntimePreviewHost runtimePreview;
 [MenuItem("Window/Habitat Shift/Level Lab R10")]static void Open(){GetWindow<R10Window>("Level Lab R10");}
 void OnEnable(){state=CreateInstance<R10EditorState>();state.hideFlags=HideFlags.HideAndDontSave;state.project=Demo();Undo.undoRedoPerformed+=Repaint;}
 void OnDisable(){Undo.undoRedoPerformed-=Repaint;if(runtimePreview!=null)runtimePreview.Dispose();if(state)DestroyImmediate(state);}
 R10Project Demo(){return new R10Project{id="NEW_DRAFT",source="NEW",level=new LevelDto{id=0,cols=6,rows=6,habitats=new[]{new HabitatDto{id="H1",color="orange",need=1,movementConstraint="FREE",anchor=new IntPair{x=0,y=0},shape=new[]{new IntPair{x=0,y=0}}}},targets=new[]{new TargetDto{id="S1",color="orange",position=new FloatPair{x=1.5f,y=.5f}}},elevators=Array.Empty<ElevatorDto>(),obstacles=Array.Empty<IntPair>()}};}
 void Activate(R10Project project,string source){state.project=R10Storage.CloneProject(project);state.project.source=source;selected.Clear();play=null;view=R10View.AUTHORING;}
 void OnGUI(){if(state==null||state.project==null)return;try{Header();Toolbar();if(showGenerator){EditorGUILayout.BeginVertical("box");try{R10GeneratorPanel.Draw(ref generatorProfile,CandidateAction);}finally{EditorGUILayout.EndVertical();}}EditorGUILayout.BeginHorizontal();try{EditorGUILayout.BeginVertical("box",GUILayout.ExpandWidth(true));try{if(view==R10View.RUNTIME_PREVIEW)DrawRuntimePreview();else if(view==R10View.PLAYTEST)DrawPlaytestBoard();else R10Canvas.Draw(state,selected,tool,grid,targets,choke,ref dragId,ref dragKind);}finally{EditorGUILayout.EndVertical();}EditorGUILayout.BeginVertical("box",GUILayout.Width(340));try{RightPanel();}finally{EditorGUILayout.EndVertical();}}finally{EditorGUILayout.EndHorizontal();}}catch(Exception e){Debug.LogException(e);EditorGUILayout.HelpBox("LEVEL LAB ERROR\n"+e.Message,MessageType.Error);}}
 void Header(){var p=state.project;var l=p.level;EditorGUILayout.BeginHorizontal("box");EditorGUILayout.LabelField("ACTIVE LEVEL: "+p.id,GUILayout.Width(205));EditorGUILayout.LabelField("SOURCE: "+p.source,GUILayout.Width(150));EditorGUILayout.LabelField("Board: "+l.cols+"?"+l.rows,GUILayout.Width(95));EditorGUILayout.LabelField("Habitats: "+(l.habitats?.Length??0),GUILayout.Width(95));EditorGUILayout.LabelField("Sproutlings: "+(l.targets?.Length??0),GUILayout.Width(110));EditorGUILayout.LabelField("Elevators: "+(l.elevators?.Length??0),GUILayout.Width(95));EditorGUILayout.LabelField("CERTIFICATION: "+p.certification.status);EditorGUILayout.EndHorizontal();}
 void Toolbar(){EditorGUILayout.BeginHorizontal(EditorStyles.toolbar);foreach(R10View v in Enum.GetValues(typeof(R10View)))if(GUILayout.Toggle(view==v,v==R10View.RUNTIME_PREVIEW?"RUNTIME PREVIEW":v.ToString(),EditorStyles.toolbarButton))view=v;if(GUILayout.Button("NEW",EditorStyles.toolbarButton)){state.project=Demo();selected.Clear();play=null;view=R10View.AUTHORING;}if(GUILayout.Button("IMPORT V5",EditorStyles.toolbarButton)){var f=EditorUtility.OpenFilePanel("Import approved V5 catalog",Application.streamingAssetsPath,"json");if(!string.IsNullOrEmpty(f))R10ImportV5Picker.Open(f,projects=>{var added=R10LibraryStore.AddImported(projects);if(projects.Count==1)Activate(projects[0],"IMPORTED_V5");R10LevelLibraryWindow.Open(project=>Activate(project,project.source));EditorUtility.DisplayDialog("V5 imported",added+" level(s) added to the persistent Level Library.","OK");});}if(GUILayout.Button("LEVEL LIBRARY",EditorStyles.toolbarButton))R10LevelLibraryWindow.Open(project=>Activate(project,project.source));if(GUILayout.Button("SAVE",EditorStyles.toolbarButton))Save(false);if(GUILayout.Button("SAVE AS",EditorStyles.toolbarButton))Save(true);if(GUILayout.Button("VALIDATE",EditorStyles.toolbarButton))Validate();if(GUILayout.Button(showGenerator?"CLOSE CANDIDATES":"GENERATOR",EditorStyles.toolbarButton))showGenerator=!showGenerator;EditorGUILayout.EndHorizontal();EditorGUILayout.BeginHorizontal(EditorStyles.toolbar);foreach(R10Tool v in Enum.GetValues(typeof(R10Tool))){var label=v==R10Tool.Habitat?"+ HABITAT":v==R10Tool.Sproutling?"+ SPROUTLING":v==R10Tool.Elevator?"+ ELEVATOR":v==R10Tool.Playable?"BOARD":v.ToString().ToUpper();if(GUILayout.Toggle(tool==v,label,EditorStyles.toolbarButton))tool=v;}grid=GUILayout.Toggle(grid,"GRID",EditorStyles.toolbarButton);targets=GUILayout.Toggle(targets,"TARGETS",EditorStyles.toolbarButton);choke=GUILayout.Toggle(choke,"CHOKE",EditorStyles.toolbarButton);reachability=GUILayout.Toggle(reachability,"REACH",EditorStyles.toolbarButton);dependency=GUILayout.Toggle(dependency,"DEPENDENCY",EditorStyles.toolbarButton);solution=GUILayout.Toggle(solution,"PATH",EditorStyles.toolbarButton);EditorGUILayout.EndHorizontal();if(view==R10View.AUTHORING&&tool!=R10Tool.Select)EditorGUILayout.HelpBox("Click a playable cell to use "+tool+".",MessageType.Info);}
 void CandidateAction(R10Candidate c,string action){if(action=="DELETE"){R10CandidateBrowser.Candidates.Remove(c);return;}Activate(c.project,"GENERATED");state.project.sourceCandidateId=c.id;if(action=="EDIT"){showGenerator=false;return;}if(action=="PLAY"){StartPlaytest();return;}view=R10View.RUNTIME_PREVIEW;}
 void StartPlaytest(){try{R10Storage.ValidateRuntimeReady(state.project.level);play=new R10Playtest(state.project.level,R10Rules.Default,state.project.sourceCatalogFingerprint);view=R10View.PLAYTEST;}catch(Exception e){EditorUtility.DisplayDialog("Play Test unavailable",e.Message,"OK");}}
 void RightPanel(){var p=state.project;if(view==R10View.AUTHORING){R10Inspector.Draw(state,selected);if(GUILayout.Button("PLAY TEST"))StartPlaytest();}else if(view==R10View.PLAYTEST){var s=play==null?null:(play.Session.Preview??play.Session.Committed);if(play==null){EditorGUILayout.HelpBox("Start a Play Test from Authoring or a candidate PLAY action.",MessageType.Info);if(GUILayout.Button("GO TO AUTHORING"))view=R10View.AUTHORING;}else{EditorGUILayout.LabelField("PLAYTEST",EditorStyles.boldLabel);EditorGUILayout.LabelField("Moves",s.moves.ToString());EditorGUILayout.LabelField(s.won?"WON":"IN PROGRESS",EditorStyles.boldLabel);if(GUILayout.Button("UNDO"))play.Undo();if(GUILayout.Button("RESTART"))play.Restart();if(GUILayout.Button("EXIT PLAYTEST")){play=null;view=R10View.AUTHORING;}}}else{EditorGUILayout.HelpBox("RUNTIME PREVIEW ? VISUAL ONLY\nUse PLAYTEST tab to interact.",MessageType.Info);if(GUILayout.Button("GO TO PLAYTEST")){if(play==null)StartPlaytest();else view=R10View.PLAYTEST;}}var report=R10Validator.Check(p);EditorGUILayout.Space();EditorGUILayout.HelpBox("STATIC VALIDATION DOES NOT PROVE SOLVABILITY",MessageType.Warning);EditorGUILayout.LabelField("Risk",R10Solver.Risk(p,R10Rules.Default).ToString());EditorGUILayout.LabelField("FATAL: "+report.findings.Count(x=>x.severity=="FATAL")+"  WARNING: "+report.findings.Count(x=>x.severity!="FATAL"));foreach(var f in report.findings)EditorGUILayout.HelpBox(f.severity+"  "+f.code+"\n"+f.detail,f.severity=="FATAL"?MessageType.Error:MessageType.Warning);if(GUILayout.Button("BACK TO CANDIDATES"))showGenerator=true;}
 void DrawRuntimePreview(){try{R10Storage.ValidateRuntimeReady(state.project.level);var area=GUILayoutUtility.GetRect(520,520,GUILayout.ExpandWidth(true),GUILayout.ExpandHeight(true));if(runtimePreview==null)runtimePreview=new R10RuntimePreviewHost();runtimePreview.Render(state.project.level,play==null?ContinuousSession.Initial(state.project.level):(play.Session.Preview??play.Session.Committed),Mathf.Max(64,(int)area.width),Mathf.Max(64,(int)area.height));if(runtimePreview.Texture!=null)GUI.DrawTexture(area,runtimePreview.Texture,ScaleMode.ScaleToFit,false);if(!string.IsNullOrEmpty(runtimePreview.Error))EditorGUI.HelpBox(area,runtimePreview.Error,MessageType.Error);}catch(Exception e){EditorGUILayout.HelpBox("RUNTIME PREVIEW UNAVAILABLE\n"+e.Message,MessageType.Error);}}
 void DrawPlaytestBoard(){if(play==null){EditorGUILayout.HelpBox("No active playtest.",MessageType.Info);return;}var l=state.project.level;var s=play.Session.Preview??play.Session.Committed;var r=GUILayoutUtility.GetRect(520,520,GUILayout.ExpandWidth(true),GUILayout.ExpandHeight(true));var cell=Mathf.Min(r.width/l.cols,r.height/l.rows);Vector2 P(Vector2 b)=>new Vector2(r.x+b.x*cell,r.y+(l.rows-b.y-1)*cell);foreach(var h in s.habitats)foreach(var q in h.shape)EditorGUI.DrawRect(new Rect(P(h.anchor+q),Vector2.one*(cell-3)),Color.cyan);foreach(var t in s.sprouts)EditorGUI.DrawRect(new Rect(P(t.position-Vector2.one*.5f)+Vector2.one*8,Vector2.one*(cell-18)),Color.yellow);var ev=Event.current;if(!r.Contains(ev.mousePosition))return;var b=new Vector2((ev.mousePosition.x-r.x)/cell,l.rows-1-(ev.mousePosition.y-r.y)/cell);if(ev.type==EventType.MouseDown&&ev.button==0){var h=s.habitats.FirstOrDefault(a=>a.shape.Any(q=>new Rect(a.anchor+q,Vector2.one).Contains(b)));if(h!=null)play.Begin(h.id,b);ev.Use();}else if(ev.type==EventType.MouseDrag&&play.Session.IsDragging){play.Move(b);ev.Use();}else if(ev.type==EventType.MouseUp&&play.Session.IsDragging){play.End();ev.Use();}}
 void Validate(){var report=R10Validator.Check(state.project);if(!report.findings.Any(x=>x.severity=="FATAL"))state.project.certification.status="STATIC_PASS";EditorUtility.DisplayDialog("Validation","Fatal: "+report.findings.Count(x=>x.severity=="FATAL")+"\nWarnings: "+report.findings.Count(x=>x.severity!="FATAL"),"OK");}
 void Save(bool saveAs){if(saveAs||string.IsNullOrEmpty(path)){path=EditorUtility.SaveFilePanel("Save Level Lab draft",R10Storage.DefaultRoot,state.project.id,"json");if(string.IsNullOrEmpty(path))return;}R10Storage.Save(state.project,path);EditorUtility.DisplayDialog("Saved",path,"OK");}
}}
#endif